import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
cores=[[3,2,2,3,None],[2,8,8,2,None],[3,2,2,3,None],[2,8,8,2,None],[None]*5]
for ri,r0 in enumerate(starts):
  for ci,c0 in enumerate(starts):
    v=cores[ri][ci]
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<n and c<n:
          if dr in (0,4) or dc in (0,4): g[r][c]=4
          elif v is not None: g[r][c]=v
